const outputs=[];let inverses=0;
function call(id,method,args){store("math_e20_reader_"+id+"_request",{method,args});const response=api[method](...args);store("math_e20_reader_"+id+"_response",response);outputs.push({id,method,args,response});store("math_e20_reader_outputs",outputs);return response;}
function inverse(id,selection,options={}){const r=call(id,"rank",[selection.mask,options]);if(!r.member||r.rank!==selection.rank)throw Error("inverse mismatch "+id);inverses++;}
const sum=call("summary","summary",[]);
const all=call("all","family",[]);
const maxOptions={min_size:10,max_size:10};
call("max_family","family",[maxOptions]);
const maxima=call("all_maxima","page",[0,1000,maxOptions]);
for(const s of maxima.items)inverse("maximum_rank_"+s.rank,s,maxOptions);
call("size9_family","family",[{min_size:9,max_size:9}]);
call("all_size9","page",[0,1000,{min_size:9,max_size:9}]);
for(const rank of [0,12345,all.count-1]){const s=call("all_select_"+rank,"select",[rank]);inverse("all_rank_"+rank,s);}
call("full_obstruction","membership",[1048575]);
call("maximum_membership","membership",[maxima.items[0].mask]);
const first=call("obstruction0","obstruction",[0]);call("obstruction59","obstruction",[59]);
const conditions=[
 {id:"force_edge0",options:{required:1}},
 {id:"force0_exclude1",options:{required:1,excluded:2}},
 {id:"force_first_two",options:{required:3}},
 {id:"force_sunflower",options:{required:first.edge_mask}},
 {id:"exclude_edge0",options:{excluded:1}},
 {id:"avoid_vertex0",options:{excluded:1023}},
 {id:"max_exclude0",options:{excluded:1,min_size:10,max_size:10}},
 {id:"max_force0",options:{required:1,min_size:10,max_size:10}}
];
for(const c of conditions){
  const f=call(c.id+"_family","family",[c.options]);
  if(f.count){for(const rank of [...new Set([0,Math.floor(f.count/2),f.count-1])]){const s=call(c.id+"_select_"+rank,"select",[rank,c.options]);inverse(c.id+"_rank_"+rank,s,c.options);}}
}
store("math_e20_reader_inverse_matches",inverses);
store("math_e20_reader_work",api.work());
store("math_e20_reader_caches",api.conditions());
